/* eslint-env node */
import React from "react";
//import ReactDOM from "react-dom";


import { createRoot } from 'react-dom/client';


import "./index.css";
import App from "./App";

const container = document.getElementById('root');
const root = createRoot(container);
root.render(  <React.StrictMode> <App /> </React.StrictMode>);
if (process.env.NODE_ENV === "production" && "serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register(`${process.env.PUBLIC_URL}/service-worker.js`)
      .then(() => navigator.serviceWorker.ready)
      .then(() => window.dispatchEvent(new Event("lbh-offline-ready")))
      .catch(() => {
        // Deck persistence remains available if app caching is unsupported.
        window.dispatchEvent(new Event("lbh-offline-unavailable"));
      });
  });
}
if (process.env.NODE_ENV === "production" && !("serviceWorker" in navigator)) {
  window.addEventListener("load", () => window.dispatchEvent(new Event("lbh-offline-unavailable")));
}
