/* eslint-env node */
import React, { Component } from "react";
import "./App.css";

import CardDisplay from "./components/CardDisplay.js";
import UserCardPlayer from "./components/UserCardPlayer";
// import ItemChain from "./components/ItemChain";

import FileLoaderForm from "./components/FileLoaderForm.js";
import Modal from 'react-modal';
import { parseQuizItems2 } from "./helpers/api.js";
import Tabs from "./components/Tabs";
import LabeledCheck from "./components/LabeledCheck.js";
import FramedSection from "./components/FramedSection.js";
import QuestionAnswer from "./components/QuestionAnswer.js"
import Collapsible from "./components/Collapsible.js";
import LangCombo from "./components/LangCombo";
import { LANGUAGE_KEY, LANGUAGES, LanguageContext, createTranslator, readLanguage } from "./helpers/i18n";
import { encryptData, decryptData} from "./helpers/utils.js"
import { DECK_KEY, SETTINGS_KEY, PASSPHRASE_KEY, REPEAT_OFFSETS_KEY, HOUR, readDeck, readExpiryHours, readRepeatOffsets, validExpiryHours, validRepeatOffset, writeDeck } from "./helpers/deckStorage";

Modal.setAppElement('#root');

const EMPTY_QUIZ_ITEM = { question: "", answer: "" };

// const Test = () =>  <div> Hello</div>

class App extends Component {
  constructor(props) {
    super(props);

    this.state = {
      QuizItems: [],
      MemorizedQuizItems: [],
      currentQuizItem: EMPTY_QUIZ_ITEM,
      isDialogOpen: true,
      fileContent:"",
      fileSeparator: "|",
      hasLoadedDeck: false,
      expiresAt: null,
      expiryHours: 24,
      storageError: "",
      uiLanguage: "en-US",
      languageStorageError: "",
      loadError: "",
      isPassphraseVisible: false,
      passphraseStorageError: "",
      repeatOffsets: [5, 10, 15],
      repeatOffsetDrafts: ["5", "10", "15"],
      repeatStorageError: "",
      reviewVersion: 0,
      offlineStatus: process.env.NODE_ENV === "production" ? "offlinePreparing" : "offlineDevelopment",
      //settings
      isLastToFirst: true,
      isAnswerLeftAligned : false,
      isAnswerMonospaceFont : false,
      answerFontSize : 32,
      isQuestionLeftAligned : false,
      isQuestionMonospaceFont : false,
      questionFontSize : 36,
      secretPass: "" //for encryption and decryption
      //end settings
    };
    try {
      this.state.uiLanguage = readLanguage(window.localStorage);
    } catch {
      // Other storage errors are reported below; English remains available.
    }
    try {
      const savedPassphrase = window.localStorage.getItem(PASSPHRASE_KEY);
      if (savedPassphrase !== null) this.state.secretPass = savedPassphrase;
    } catch {
      this.state.passphraseStorageError = "passphraseReadFailed";
    }
    try {
      this.state.expiryHours = readExpiryHours(window.localStorage);
      this.state.repeatOffsets = readRepeatOffsets(window.localStorage);
      this.state.repeatOffsetDrafts = this.state.repeatOffsets.map(String);
      const saved = readDeck(window.localStorage);
      if (saved) {
        this.state = {
          ...this.state,
          QuizItems: saved.QuizItems,
          MemorizedQuizItems: saved.MemorizedQuizItems,
          currentQuizItem: saved.QuizItems[0] ?? EMPTY_QUIZ_ITEM,
          fileContent: saved.fileContent,
          fileSeparator: saved.fileSeparator,
          expiresAt: saved.expiresAt,
          hasLoadedDeck: saved.hasLoadedDeck === true,
          isDialogOpen: saved.hasLoadedDeck !== true,
        };
      }
    } catch {
      this.state.storageError = "storageUnavailable";
    }
    //console.log(this.state.QuizItems);
  }

  componentDidMount() {
    document.documentElement.lang = this.state.uiLanguage.split("-")[0];
    this.expiryTimer = window.setInterval(this.checkExpiry, 30000);
    window.addEventListener("focus", this.checkExpiry);
    window.addEventListener("lbh-offline-ready", this.onOfflineReady);
    window.addEventListener("lbh-offline-unavailable", this.onOfflineUnavailable);
  }

  componentWillUnmount() {
    window.clearInterval(this.expiryTimer);
    window.removeEventListener("focus", this.checkExpiry);
    window.removeEventListener("lbh-offline-ready", this.onOfflineReady);
    window.removeEventListener("lbh-offline-unavailable", this.onOfflineUnavailable);
  }

  onOfflineReady = () => this.setState({ offlineStatus: "offlineReady" });
  onOfflineUnavailable = () => this.setState({ offlineStatus: "offlineUnavailable" });

  changeLanguage = (event) => {
    const uiLanguage = event.target.value;
    if (!LANGUAGES.some(({ code }) => code === uiLanguage)) return;
    this.setState({ uiLanguage });
    try {
      window.localStorage.setItem(LANGUAGE_KEY, uiLanguage);
      this.setState({ languageStorageError: "" });
    } catch {
      this.setState({ languageStorageError: "languageSaveFailed" });
    }
  };

  changePassphrase = (event) => {
    const secretPass = event.target.value;
    this.setState({ secretPass });
    try {
      if (secretPass === "") window.localStorage.removeItem(PASSPHRASE_KEY);
      else window.localStorage.setItem(PASSPHRASE_KEY, secretPass);
      this.setState({ passphraseStorageError: "" });
    } catch {
      this.setState({ passphraseStorageError: secretPass === ""
        ? "passphraseForgetFailed"
        : "passphraseSaveFailed" });
    }
  };

  changeRepeatOffset = (index, value) => {
    const offset = Number(value);
    const valid = validRepeatOffset(offset);
    this.setState((state) => ({
      repeatOffsetDrafts: state.repeatOffsetDrafts.map((draft, slot) => slot === index ? value : draft),
      repeatOffsets: valid ? state.repeatOffsets.map((previous, slot) => slot === index ? offset : previous) : state.repeatOffsets,
    }), () => {
      if (!valid) return;
      try {
        window.localStorage.setItem(REPEAT_OFFSETS_KEY, JSON.stringify(this.state.repeatOffsets));
        this.setState({ repeatStorageError: "" });
      } catch {
        this.setState({ repeatStorageError: "repeatSaveFailed" });
      }
    });
  };

  // eslint-disable-next-line no-unused-vars
  componentDidUpdate(previousProps, previousState) {
    if (previousState.uiLanguage !== this.state.uiLanguage) {
      document.documentElement.lang = this.state.uiLanguage.split("-")[0];
    }
    if (this.state.expiresAt && (
      previousState.fileContent !== this.state.fileContent ||
      previousState.fileSeparator !== this.state.fileSeparator ||
      previousState.QuizItems !== this.state.QuizItems ||
      previousState.MemorizedQuizItems !== this.state.MemorizedQuizItems ||
      previousState.expiresAt !== this.state.expiresAt ||
      previousState.hasLoadedDeck !== this.state.hasLoadedDeck
    )) {
      try {
        writeDeck(window.localStorage, this.state);
        if (this.state.storageError) this.setState({ storageError: "" });
      } catch {
        if (!this.state.storageError) this.setState({
          storageError: "deckSaveFailed",
        });
      }
    }
  }

  clearSavedDeck = () => {
    let storageError = "";
    try {
      window.localStorage.removeItem(DECK_KEY);
    } catch {
      storageError = "deckClearFailed";
    }
    this.setState({
      QuizItems: [], MemorizedQuizItems: [], currentQuizItem: EMPTY_QUIZ_ITEM,
      fileContent: "", fileSeparator: "|", hasLoadedDeck: false,
      expiresAt: null, isDialogOpen: true, storageError,
    });
  };

  checkExpiry = () => {
    if (this.state.expiresAt && this.state.expiresAt <= Date.now()) {
      this.clearSavedDeck();
      return true;
    }
    return false;
  };

  changeExpiryHours = (event) => {
    const expiryHours = Number(event.target.value);
    if (!validExpiryHours(expiryHours)) return;
    this.setState({ expiryHours, expiresAt: this.state.expiresAt ? Date.now() + expiryHours * HOUR : null });
    try {
      window.localStorage.setItem(SETTINGS_KEY, JSON.stringify(expiryHours));
    } catch {
      this.setState({ storageError: "expirySaveFailed" });
    }
  };


  onContentLoaded(fileLoadData) {
    //console.log(this.state.QuizItems);this.setState({ fileContent: e.target.value })
    this.setState({
      fileContent: fileLoadData.content,
      fileSeparator: fileLoadData.separator,
      expiresAt: Date.now() + this.state.expiryHours * HOUR
    });
  }

  loadQuizFromContent () {
    if (this.checkExpiry()) return;
    // console.log(this.state.isLastToFirst);
    let quizItems;
    try {
      quizItems = parseQuizItems2(this.state.fileSeparator,this.state.fileContent,this.state.isLastToFirst);
      if (!quizItems.length) throw new Error("Empty deck");
    } catch {
      this.setState({ loadError: "invalidDeck" });
      return;
    }
    this.setState({
      QuizItems: quizItems,
      MemorizedQuizItems: [],
      currentQuizItem: quizItems && quizItems?.length > 0? quizItems[0]: EMPTY_QUIZ_ITEM,
      isDialogOpen:false,
      hasLoadedDeck: true,
      loadError: "",
      expiresAt: Date.now() + this.state.expiryHours * HOUR
    });
  }

  OnCurrentQuizItemChanged(qi){
    this.setState({currentQuizItem:qi}) ; 
    // console.log("updated",qi);
  }

  // goToNextItem(isCurrentItemDropped = false) {
  //   if( !isCurrentItemDropped ) {
  //     this.state.MemorizedQuizItems.unshift(this.state.QuizItems[0]);          
  //   }
  //   this.state.QuizItems.splice(0, 1); //remove item from start
  //   if (this.state.QuizItems.length === 0) {
  //     //finish quiz
  //     //alert("No more items left");
  //     this.forceUpdate();
  //     this.OnCurrentQuizItemChanged({ question: "", answer: "" });
  //     return;
  //   }
  //   //this.recalculateVisuals(this.state.currentQuizItemIndex);
  //   this.OnCurrentQuizItemChanged(this.state.QuizItems[0]);
  // }

  goToNextItem = (isCurrentItemDropped = false) => {
    if (this.checkExpiry()) return;
    this.setState((previousState) => {
      const [currentItem, ...remainingItems] = previousState.QuizItems;

      if (!currentItem) {
        return null;
      }

      return {
        expiresAt: isCurrentItemDropped ? previousState.expiresAt : Date.now() + previousState.expiryHours * HOUR,
        QuizItems: remainingItems,
        MemorizedQuizItems: isCurrentItemDropped
          ? previousState.MemorizedQuizItems
          : [currentItem, ...previousState.MemorizedQuizItems],
        currentQuizItem: remainingItems[0] ?? EMPTY_QUIZ_ITEM,
      };
    });
  };

  showCurrentItemInNCards = (offset) => {
    if (this.checkExpiry()) return;
    this.setState((previousState) => {
      const quizItems = [...previousState.QuizItems];

      if (quizItems.length === 0) {
        return null;
      }

      const [currentItem] = quizItems.splice(0, 1);
      const targetIndex = Math.min(
        Math.max(offset, 0), quizItems.length
      );

      quizItems.splice(targetIndex, 0, currentItem);

      return {
        expiresAt: Date.now() + previousState.expiryHours * HOUR,
        reviewVersion: previousState.reviewVersion + 1,
        QuizItems: quizItems,
        currentQuizItem: quizItems[0] ?? EMPTY_QUIZ_ITEM,
      };
    });
  };

updateCurrentQuizItem = ({ question, answer }) => {
  if (this.checkExpiry()) return;
  this.setState((previousState) => {
    const currentItem = previousState.currentQuizItem;

    if (!currentItem || previousState.QuizItems.length === 0) {
      return null;
    }

    const updatedItem = {
      ...currentItem,
      question,
      answer,
    };

    return {
      QuizItems: previousState.QuizItems.map((item) =>
        item === currentItem ? updatedItem : item
      ),
      currentQuizItem: updatedItem,
    };
  });
};

  copyFileToClipboard = () => {
    document.getElementById("finalFileContent").select();
    document.execCommand("copy");
  };

  onEncrypt = () => {
    const text = encryptData(this.state.secretPass,this.state.fileContent )
    this.setState( { fileContent : text} )
  }

  onDecrypt = () => {
    try{
      const text = decryptData(this.state.secretPass,this.state.fileContent )
      this.setState( { fileContent : text} )      
    }
    catch {
      alert(createTranslator(this.state.uiLanguage)("decryptFailed"))
    }
  }

  render() {
    const t = createTranslator(this.state.uiLanguage);
    const remaining = this.state.QuizItems.length;
    const memorized = this.state.MemorizedQuizItems.length;
    const total = remaining + memorized;
    const progress = total ? Math.round(memorized / total * 100) : 0;
    return (
      <LanguageContext.Provider value={this.state.uiLanguage}>
      <div className="entireScreen">
        {this.state.storageError && <p className="storage-alert" role="alert">{t(this.state.storageError)}</p>}
        {this.state.languageStorageError && !this.state.isDialogOpen && <p className="storage-alert" role="alert">{t(this.state.languageStorageError)}</p>}

        <div className="ControlPanel">

          <div className="BGImage">
            <div className="AppHeader">
              <a className="brand" href="./" aria-label={t("home")}>
                <span className="brand-mark" aria-hidden="true">L</span>
                <span>LBH<span className="brand-subtitle">{t("flashcards")}</span></span>
              </a>
              <div className="header-actions">
                <a className="populator-link" href="https://jwidht.github.io/LBH-Catalogue/code/lbh-populator-react/build/" target="_blank" rel="noreferrer">{t("createDeck")} <span aria-hidden="true">↗</span></a>
                <button className="btn" onClick={()=>this.setState({ isDialogOpen:true, loadError: "" })}><span aria-hidden="true">+</span> {t("loadDeck")}</button>
              </div>
              <label className="language-picker">
                <LangCombo language={this.state.uiLanguage} onChange={this.changeLanguage} />
              </label>
            </div>
          </div>

          
      <Modal
        isOpen={this.state.isDialogOpen}
        onRequestClose={()=>this.setState({ isDialogOpen: false })}
        className="load-modal"
        overlayClassName="load-overlay"
        // onAfterOpen={afterOpenModal}
        // onRequestClose={closeModal}
        // style={customStyles}
        contentLabel={t("loadModal")}
      >  
        <div className="modal-heading"><div><span className="eyebrow">{t("nextSession")}</span><h2>{t("loadDeckTitle")}</h2></div>
          <button className="close-button" aria-label={t("closeLoad")} onClick={()=>this.setState({ isDialogOpen: false })}>×</button>
        </div>
        <p className="modal-description">{t("loadDescription")}</p>
        {this.state.languageStorageError && <p className="load-error" role="alert">{t(this.state.languageStorageError)}</p>}
         <FileLoaderForm onContentLoaded={(fileLoadData) => this.onContentLoaded(fileLoadData)}/>

         <Collapsible header={t("encryption")}>
          <label className="passphrase-label" htmlFor="encryption-passphrase">{t("passphrase")}</label>
          <div className="passphrase-field">
            <input id="encryption-passphrase" type={this.state.isPassphraseVisible ? "text" : "password"}
              value={this.state.secretPass} onChange={this.changePassphrase} autoComplete="off" spellCheck={false} />
            <button type="button" className="passphrase-toggle"
              aria-label={this.state.isPassphraseVisible ? t("hidePassphrase") : t("showPassphrase")}
              aria-pressed={this.state.isPassphraseVisible}
              onClick={()=>this.setState((state)=>({ isPassphraseVisible: !state.isPassphraseVisible }))}>
              <svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
                <path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z" />
                <circle cx="12" cy="12" r="3" />
                {this.state.isPassphraseVisible && <path d="m3 3 18 18" />}
              </svg>
            </button>
          </div>
          <p>{t("passphraseHint")}</p>
          {this.state.passphraseStorageError && <p role="alert">{t(this.state.passphraseStorageError)}</p>}
          <button title={t("encryptTitle")} onClick={() => this.onEncrypt()}>{t("encrypt")}</button>
          <button title={t("decryptTitle")} onClick={() => this.onDecrypt()}>{t("decrypt")}</button>
          </Collapsible>


         <label className="field-label" htmlFor="filecontent">{t("deckContent")} <span>{t("recordHint")}</span></label>
         <textarea
          id="filecontent"
          placeholder={t("deckPlaceholder")}
          //cols="100"
          rows="8"
          style={{
            width : "100%",
            whiteSpace: "nowrap",
            overflow: "auto",
            placeholder: "The file content will appear here",
          }}
          value={this.state.fileContent}
          onChange={(e) => this.setState({ fileContent: e.target.value,
            expiresAt: this.state.expiresAt ?? Date.now() + this.state.expiryHours * HOUR })}
        ></textarea>
        {/* <h2 ref={(_subtitle) => (subtitle = _subtitle)}>Hello</h2> */}
        <Collapsible open header={t("loadingOptions")}>
        {/* <FramedSection open title="Load Options"> */}

        <label>
          {t("separator")} {" "}
          <select value={this.state.fileSeparator} onChange={(event)=>this.setState({ fileSeparator: event.target.value })}>
            <option value="|">{t("pipe")}</option><option value=",">{t("comma")}</option>
          </select>
        </label><br />
        <label>
          <input type="checkbox" checked={this.state.isLastToFirst}
            onChange={()=>this.setState({isLastToFirst:!this.state.isLastToFirst})} />
          &nbsp;{t("reverseOrder")}
        </label> <br/>   
        <label>
          <input type="checkbox" checked={this.state.isAnswerLeftAligned}
            onChange={()=>this.setState({isAnswerLeftAligned:!this.state.isAnswerLeftAligned})} />
          &nbsp;{t("answerLeft")}
        </label> <br/>   
        <label>
          <input type="checkbox" checked={this.state.isAnswerMonospaceFont}
            onChange={()=>this.setState({isAnswerMonospaceFont:!this.state.isAnswerMonospaceFont})} />
          &nbsp;{t("monospaceLoad")}
        </label>      
        {/* <br/>    </FramedSection> */}
        </Collapsible>

        {this.state.loadError && <p className="load-error" role="alert">{t(this.state.loadError)}</p>}
        <div className="modal-actions">
          <button onClick={()=>this.setState({isDialogOpen : false})}>{t("cancel")}</button>
          <button className="primary-button" onClick={()=>this.loadQuizFromContent()}>{t("startStudying")} <span aria-hidden="true">→</span></button>
        </div>

      </Modal> 
      
      
       </div>

      <main className="workspace">
       <Tabs>
          <div label={t("study")}>
            <section className="study-session">
              <div className="session-summary">
                {this.state.expiresAt && !this.state.storageError && <span className="session-badge" role="status">
                  <span className="badge-dot" aria-hidden="true" />
                  <span>{t("savedUntil")} <time dateTime={new Date(this.state.expiresAt).toISOString()}>{new Date(this.state.expiresAt).toLocaleString(this.state.uiLanguage)}</time></span>
                </span>}
              </div>
              <div className="progress-row"><progress value={memorized} max={total || 1} aria-label={t("memorizedCards")} /><span>{t("memorizedPercent", { count: progress })}</span></div>
            {remaining > 0 ? <>
            <UserCardPlayer QuizItems={this.state.QuizItems}
              isActive={!this.state.isDialogOpen}
              repeatOffsets={this.state.repeatOffsets}
              goToNextItem={()=>this.goToNextItem(false)} onShowInNCards={this.showCurrentItemInNCards} />
            <CardDisplay currentQuizItem={this.state.currentQuizItem}
            isActive={!this.state.isDialogOpen}
            reviewVersion={this.state.reviewVersion}
            isAnswerLeftAligned={this.state.isAnswerLeftAligned} 
            isAnswerMonospaceFont={this.state.isAnswerMonospaceFont}
            isQuestionLeftAligned={this.state.isQuestionLeftAligned} 
            isQuestionMonospaceFont={this.state.isQuestionMonospaceFont}
            qFontSize={parseInt(this.state.questionFontSize)}
            aFontSize={parseInt(this.state.answerFontSize)}
            />
            </> : <div className="empty-state">
              <span className="empty-symbol" aria-hidden="true">{this.state.hasLoadedDeck ? "✓" : "+"}</span>
              <h3>{this.state.hasLoadedDeck ? t("complete") : t("emptyTitle")}</h3>
              <p>{this.state.hasLoadedDeck ? t("completeHint") : t("emptyHint")}</p>
              <button className="primary-button" onClick={()=>this.setState({ isDialogOpen: true })}>{t("loadDeckTitle")}</button>
            </div>}
            </section>
          </div>
          <div label={t("leftTab", { count: this.state.QuizItems.length })}>
            <div className="section-heading"><h2>{t("reviewQueue")}</h2><p>{t("queueHint")}</p></div>
            {remaining === 0 && <p className="list-empty">{t("queueEmpty")}</p>}
            <div className="card-grid">
            {
                this.state.QuizItems.map( 
                    (item, idx)=> {
                                return <div key={item.id ?? idx} className="crdLeft"><span className="card-label">{t("cardNumber", { count: idx + 1 })}</span><p>{item.question}</p><p>{item.answer}</p></div>
                            }
                    )
            }
            </div>
          </div>
          <div label={t("memorizedTab", { count: this.state.MemorizedQuizItems.length })}>
          <div className="section-heading"><h2>{t("memorizedCards")}</h2><p>{t("memorizedHint")}</p></div>
          {memorized === 0 && <p className="list-empty">{t("memorizedEmpty")}</p>}
          <div className="card-grid">
          {
                this.state.MemorizedQuizItems.map( 
                    (item, idx)=> {
                                return <div key={item.id ?? idx} className="crdMem"><span className="card-label">{t("memorized")}</span><p>{item.question}</p><p>{item.answer}</p></div>
                            }
                    )
            }
            </div>
          </div>
          <div label={t("settings")}>
           {
            <div className="settings-layout">
              <div className="section-heading"><h2>{t("settings")}</h2><p>{t("settingsHint")}</p></div>

<FramedSection title={t("repeatButtons")}>
  <div className="repeat-settings">
    {this.state.repeatOffsetDrafts.map((value, index) => <label key={index}>
      {t("repeatSetting", { count: index + 1 })}
      <input type="number" min="1" step="1" value={value}
        aria-describedby="repeat-buttons-help"
        aria-invalid={!validRepeatOffset(Number(value))}
        onChange={(event)=>this.changeRepeatOffset(index, event.target.value)} />
    </label>)}
  </div>
  <p id="repeat-buttons-help">{t("repeatSettingsHint")}</p>
  <p>{t("repeatHelp")}</p>
  {this.state.repeatStorageError && <p role="alert">{t(this.state.repeatStorageError)}</p>}
</FramedSection>

<FramedSection title={t("offlineStorage")}>
  <label>
    {t("expiryHours")} {" "}
    <input type="number" min="1" max="8760" value={this.state.expiryHours} onChange={this.changeExpiryHours} />
  </label>
  <p>{t("expiryHint")}</p>
  <p>{t(this.state.offlineStatus)}</p>
  <p>{this.state.expiresAt ? t("expiresAt", { date: new Date(this.state.expiresAt).toLocaleString(this.state.uiLanguage) }) : t("noDeckSaved")}</p>
  <p>{t("expiryCleanup")}</p>
  <button onClick={this.clearSavedDeck}>{t("clearDeck")}</button>
</FramedSection>

<FramedSection title={t("question")}>

  <LabeledCheck lbl={t("leftAligned")} checked={this.state.isQuestionLeftAligned} onChange={()=>this.setState({isQuestionLeftAligned:!this.state.isQuestionLeftAligned})}/>
  <LabeledCheck lbl={t("monospaceLoad")} checked={this.state.isQuestionMonospaceFont} onChange={()=>this.setState({isQuestionMonospaceFont:!this.state.isQuestionMonospaceFont})}/>

  <div className="slidecontainer">
  <input type="range" aria-label={t("questionFontSize")} min="12" max="100" value={this.state.questionFontSize}
  onChange={evt => this.setState({questionFontSize: evt.target.value})}
  id="myRange1"/>
  </div>
  <div style={{fontSize: this.state.questionFontSize + 'px'}}>{t("sampleQuestion")}</div> 

</FramedSection>

<FramedSection title={t("answer")}>
 
  <LabeledCheck lbl={t("leftAligned")} checked={this.state.isAnswerLeftAligned} onChange={()=>this.setState({isAnswerLeftAligned:!this.state.isAnswerLeftAligned})}/>
  <LabeledCheck lbl={t("monospaceLoad")} checked={this.state.isAnswerMonospaceFont} onChange={()=>this.setState({isAnswerMonospaceFont:!this.state.isAnswerMonospaceFont})}/>
  <div className="slidecontainer">
    <input type="range" aria-label={t("answerFontSize")} min="12" max="100" value={this.state.answerFontSize}
    onChange={evt => { this.setState({answerFontSize: evt.target.value}) } }
    id="myRange2"/>
    </div>
    <div style={{fontSize: this.state.answerFontSize + 'px'}}>{t("sampleAnswer")}</div> 

  </FramedSection>

            </div>

            }
          </div>         

          <div label={t("edit")}>
              <div className="section-heading"><h2>{t("editCard")}</h2><p>{t("editHint")}</p></div>
              <QuestionAnswer currentQuizItem={this.state.currentQuizItem} 
              hasItem={remaining > 0}
              onUpdateCurrentItem={this.updateCurrentQuizItem}
              deleteCurrentEntirely={()=>this.goToNextItem(true)}   />
          </div>

          <div label={t("file")}>
          <div className="section-heading"><h2>{t("exportDeck")}</h2><p>{t("exportHint")}</p></div>
          <FramedSection title={t("finalFile")}>
              <textarea
                id="finalFileContent"
                aria-label={t("generatedContent")}
                cols="60"
                rows="20"
                style={{width:"100%",
                  whiteSpace: "nowrap",
                  overflow: "auto",
                  placeholder: "The file content will appear here",
                }}
                // placeholder={placeholderQ}
                //defaultValue={this.state.quizQuestion}
                // value={this.state.quizQuestion}
                // onChange={(e) =>
                //   this.setState({ quizQuestion: e.target.value })
                // }
                defaultValue={
                this.state.MemorizedQuizItems.toReversed().map( 
                    (item)=> {
                                return `${item.question.replace(/[\n\r]/g, "~~").replaceAll("|","||")}|${item.answer.replace(/[\n\r]/g, "~~").replaceAll("|","||")}`
                            }
                    ).join("\n")
                    +"\n"+
                    this.state.QuizItems.map( 
                      (item)=> {
                                  return `${item.question.replace(/[\n\r]/g, "~~").replaceAll("|","||")}|${item.answer.replace(/[\n\r]/g, "~~").replaceAll("|","||")}`
                              }
                      ).join("\n")                 
            }

              >
              
                </textarea>
             

              </FramedSection>

        <button onClick={() => this.copyFileToClipboard()}>
         {t("copy")}
        </button>
          </div>


        </Tabs>   
        </main>

      </div>
      </LanguageContext.Provider>
    );
  }
}

export default App;
