import { LanguageContext, createTranslator } from "../helpers/i18n";
import React, { Component } from "react";
import "./CardDisplay.css";
import PropTypes from "prop-types";

class CardDisplay extends Component {
  static contextType = LanguageContext;

  state = { isAnswerVisible: false };

  componentDidMount() {
    window.addEventListener("keydown", this.handleKeyDown);
  }

  componentWillUnmount() {
    window.removeEventListener("keydown", this.handleKeyDown);
  }

  handleKeyDown = (event) => {
    if (event.key !== "ArrowDown" || event.defaultPrevented || event.altKey ||
        event.ctrlKey || event.metaKey || event.shiftKey || this.props.isActive === false ||
        this.state.isAnswerVisible) return;
    const target = event.target;
    if (target.closest && target.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])')) return;
    event.preventDefault();
    this.setState({ isAnswerVisible: true });
  };

  componentDidUpdate(prevProps) {
    if (this.props.currentQuizItem !== prevProps.currentQuizItem ||
        this.props.reviewVersion !== prevProps.reviewVersion) {
      this.setState({ isAnswerVisible: false });
    }
  }

  render() {
    const t = createTranslator(this.context);
    const { currentQuizItem, isQuestionLeftAligned, isQuestionMonospaceFont,
      isAnswerLeftAligned, isAnswerMonospaceFont, qFontSize, aFontSize } = this.props;
    return (
      <article className="CardDisplayArea" aria-label={t("currentFlashcard")}>
        <div className="card-face question-face">
          <span className="card-label">{t("question")}</span>
          <div className={`CardQuestion display-linebreak ${isQuestionLeftAligned ? "leftAlign" : ""} ${isQuestionMonospaceFont ? "preformatted" : ""}`}
            style={{ fontSize: qFontSize + "px" }}>{currentQuizItem.question}</div>
        </div>
        <div className="card-face answer-face">
          <span className="card-label">{t("answer")}</span>
          {this.state.isAnswerVisible ? (
            <div className={`CardAnswer display-linebreak ${isAnswerLeftAligned ? "leftAlign" : ""} ${isAnswerMonospaceFont ? "preformatted" : ""}`}
              style={{ fontSize: aFontSize + "px" }} aria-live="polite">{currentQuizItem.answer}</div>
          ) : (
            <div className="answer-prompt">
              <button className="reveal-button" aria-label={t("revealAnswer")} aria-keyshortcuts="ArrowDown" onClick={() => this.setState({ isAnswerVisible: true })}>
                {t("revealAnswer")} <kbd aria-hidden="true">↓</kbd>
              </button>
            </div>
          )}
        </div>
      </article>
    );
  }
}

CardDisplay.propTypes = {
  currentQuizItem: PropTypes.object.isRequired,
  reviewVersion: PropTypes.number,
  isActive: PropTypes.bool,
  isAnswerMonospaceFont: PropTypes.bool,
  isAnswerLeftAligned: PropTypes.bool,
  isQuestionMonospaceFont: PropTypes.bool,
  isQuestionLeftAligned: PropTypes.bool,
  aFontSize: PropTypes.number,
  qFontSize: PropTypes.number,
};
export default CardDisplay;
