import CryptoJS from "crypto-js";

export const defaultStatusFormatter = (current, total) =>
  `${current} of ${total}`;

export const arrayMoveItem = (arr, fromIndex, toIndex) => {
  //moves an array item from fromIndex to toIndex
  if (arr.length < 2) return; //0 or 1 item - this makes no sense
  const maxItemIndex = arr.length - 1;
  var element = arr[fromIndex];
  arr.splice(fromIndex, 1); //remove from fromIndex
  arr.splice(Math.min(toIndex, maxItemIndex), 0, element); //insert into toIndex
};

export const encryptData = (secretPass, text) => {
  const data = CryptoJS.AES.encrypt(
    JSON.stringify(text),
    secretPass
  ).toString();

  return data;
};

export  const decryptData = (secretPass, text) => {
  const bytes = CryptoJS.AES.decrypt(text, secretPass);
  const data = JSON.parse(bytes.toString(CryptoJS.enc.Utf8));
  return data;
};
