import { LanguageContext, createTranslator, repeatLabel } from "../helpers/i18n";
import "./NextTimeSelector.css";
import React, { Component } from "react";
import PropTypes from "prop-types";

class NextTimeSelector extends Component {
  static contextType = LanguageContext;

  render() {
    const t = createTranslator(this.context);
    const { disabled, offsets, onNextTimeSelected } = this.props;
    return (
      <div className="repeat-presets" aria-label={t("repeatDelays")}>
        {offsets.map((offset, index) => (
          <button key={index} className="repeat-button" disabled={disabled}
            aria-label={repeatLabel(this.context, offset)} aria-keyshortcuts={String(index + 1)}
            onClick={() => onNextTimeSelected(offset)}>
            {repeatLabel(this.context, offset)}
            <kbd aria-hidden="true">{index + 1}</kbd>
          </button>
        ))}
      </div>
    );
  }
}

NextTimeSelector.propTypes = {
  disabled: PropTypes.bool,
  offsets: PropTypes.arrayOf(PropTypes.number).isRequired,
  onNextTimeSelected: PropTypes.func.isRequired,
};
export default NextTimeSelector;
