import { LanguageContext, createTranslator } from "../helpers/i18n";
import React, { Component } from "react";
import axios from "axios";
import {
  // getQuizItems,
  //parseQuizItems,
  parseQuizList,
  parseFrontBackLanguages,
  name2inLineSeparator,
} from "../helpers/api.js";
import PropTypes from "prop-types";
// import FramedSection from "./FramedSection.js";
import Collapsible from "./Collapsible.js";

class FileLoaderForm extends Component {
  static contextType = LanguageContext;

  constructor(props) {
    super(props);
    this.state = {
      baseLocation:  "https://raw.githubusercontent.com/jwidht/LBH-Catalogue/master/",
      catFileName: "bylanguage.psv.txt",
      languagePairs: [], //parseFrontBackLanguages("sd"),
      quizList: [],
      fileUrl:
        "https://raw.githubusercontent.com/jwidht/En-US_Ru-RU/master/Animals.psv.txt",
      items: [],
      loading: true,
      //loading from catalog file:
      indexLocation: ""
    };

    this.langPairChanged.bind(this);
  }

  componentDidMount() {
    if (navigator.onLine) this.populateLanguagePairs();
  }
  populateLanguagePairs() {

    const url = this.state.baseLocation + this.state.catFileName;// + "bylanguage.psv.txt"
    console.log("getting " + url)
    axios
      .get(
        url //"https://raw.githubusercontent.com/jwidht/LBH-Catalogue/master/bylanguage.psv.txt"
      )
      .then((response) => {
        //console.log(response);
        if (response.status !== 200) {
          alert(createTranslator(this.context)("networkFailed"));
          return;
        }
        const pairsArray = parseFrontBackLanguages(response.data);
        //this.state.languagePairs = pairsArray;
        this.setState({ languagePairs: pairsArray });
        //this.props.onContentLoaded(response.data);
        //const response = result.data;
        //this.setState({ trips: response, loading: false });
      })
      .catch(() => {
        alert(createTranslator(this.context)("networkFailed"));
      });
  }

  quizChanged(event) {
    if (event.target.value === "0") return; // - select -
    const fileUrl = event.target.value.startsWith("http")?event.target.value:this.state.baseLocation + this.state.indexLocation.trim() + event.target.value;
    console.log("loading " + fileUrl);
    this.setState({ fileUrl: fileUrl });

    axios
      .get(fileUrl)
      .then((response) => {
        //console.log(response);
        if (response.status !== 200) {
          alert(createTranslator(this.context)("networkFailed"));
          return;
        }
        //console.log(response.data);
        const fileLoadData = {
          url: fileUrl,
          separator: name2inLineSeparator(fileUrl),
          content : response.data
        }

        this.props.onContentLoaded(fileLoadData);//quizItems
        //const response = result.data;
        //this.setState({ trips: response, loading: false });
      })
      .catch(() => {
        alert(createTranslator(this.context)("networkFailed"));
      });
  }

  loadFromIndexFileAtUrl(url){
    if(!url) {
      alert(createTranslator(this.context)("urlMissing"));
      return;
    }
//console.log(url);
   const indexFileUrl = `${url}/index.psv.txt`
    axios
      .get(indexFileUrl)
      .then((response) => {
        //console.log(response);
        if (response.status !== 200) {
          alert(createTranslator(this.context)("networkFailed"));
          return;
        }
        const qList = parseQuizList(response.data);
        //console.log(qList);
        this.setState({ quizList: qList });
        //this.props.onContentLoaded(response.data);
        //const response = result.data;
        //this.setState({ trips: response, loading: false });
      })
      .catch(() => {
        alert(createTranslator(this.context)("networkFailed"));
      });
  }

  langPairChanged(event) {
    //console.log(event.target.value);
    if (event.target.value === "0") return; // - select -
    const quizListFileName = event.target.value;
    this.setState({indexLocation:quizListFileName})
    const url = this.state.baseLocation + quizListFileName;// + "index.psv.txt";
    this.loadFromIndexFileAtUrl(url);
  }

  buttonLoadClicked(){
    const baseIndexUrl= this.state.baseLocation + this.state.indexLocation.trim()
    if(baseIndexUrl =="") {
      alert(createTranslator(this.context)("baseUrlEmpty"));
      return;
    }
    this.loadFromIndexFileAtUrl(baseIndexUrl) //`${baseIndexUrl}/index.psv.txt`);
  }

  render() {
    const t = createTranslator(this.context);
    return (
      <div >
        {/* , style={{ padding: "0px 5px" }}borderBottom: "black solid 1px" */}

        <Collapsible closed header={t("sharedDatabase")}>
          <p>{t("selectLanguages")}</p>
          <select aria-label={t("selectLanguages")} onChange={(e) => this.langPairChanged(e)}>
            <option key={-1} value={0}>
              {t("selectOption")}
            </option>
            {this.state.languagePairs.map((pair) => (
              <option key={pair.pairName} value={pair.fileQuizList}>
                {pair.pairName}
              </option>
            ))}
          </select>

          <p>{t("selectDeck")}</p>
          <select aria-label={t("selectDeck")} onChange={(e) => this.quizChanged(e)}>
            <option key={-1} value={0}>
              {t("selectOption")}
            </option>
            {this.state.quizList.map((pair) => (
              <option key={pair.name} value={pair.url}>
                {pair.name}
              </option>
            ))}
          </select>

        </Collapsible>

        <Collapsible header={t("advancedSettings")}>

          {t("baseUrl")}<br/>
          <input type="text" aria-label={t("baseUrl")} style={{width:"60%",padding:"5px"}} value={this.state.baseLocation} onChange={(evt)=>this.setState({baseLocation:evt.target.value})} /><br/>
          {t("categoriesFile")}<br/><input type="text" aria-label={t("categoriesFile")} style={{width:"120px",padding:"5px"}} value={this.state.catFileName} onChange={(evt)=>this.setState({catFileName:evt.target.value})} />
          <button onClick={() => this.populateLanguagePairs() }>{t("loadCategories")}</button> <br/>

          {t("indexLocation")}  <br/>
          <input style={{width:"120px",padding:"5px"}} type="text" aria-label={t("indexLocation")} value={this.state.indexLocation} onChange={(evt)=>this.setState({indexLocation:evt.target.value})} />
          <button title={t("loadIndexTitle")} onClick={() => this.buttonLoadClicked()}>{t("loadIndex")}</button>

          </Collapsible>

      </div>
    );
  }
}

FileLoaderForm.propTypes = {
  onContentLoaded: PropTypes.func.isRequired, //the function that will set is visible to true
};

export default FileLoaderForm;
