import React from "react";
import PropTypes from "prop-types";
import "./Collapsible.css";

export default function Collapsible({ open, children, header }) {
  return (
    <details className="collapsible-card-edonec" open={open}>
      <summary className="collapsible-header-edonec">{header}</summary>
      <div className="collapsible-content-padding-edonec">{children}</div>
    </details>
  );
}

Collapsible.propTypes = {
  open: PropTypes.bool,
  header: PropTypes.string,
  children: PropTypes.node,
};
