
import React from "react"; //, { Component }
import PropTypes from "prop-types";


export default function LabeledCheck(props){
    return <>
        <label>
        <input type="checkbox" checked={props.checked} onChange={props.onChange} />&nbsp;{props.lbl}
      </label> <br/>  
    </>
  }

  LabeledCheck.propTypes = {
    checked: PropTypes.bool.isRequired,//what to show
    onChange: PropTypes.func.isRequired,//what to show
    lbl: PropTypes.string.isRequired,//what to show
  };