import React, { Component } from 'react';
import PropTypes from 'prop-types';
import "./Tab.css";

class Tab extends Component {
  static propTypes = {
    activeTab: PropTypes.string.isRequired,
    label: PropTypes.string.isRequired,
    onClick: PropTypes.func.isRequired,
      onClickIndex: PropTypes.func,
      index : PropTypes.number,
      activeTabIndex : PropTypes.number,
};

  onClick = () => {
    const { label, onClickIndex, index } = this.props; //onClick,
    //onClick(label);
    onClickIndex(label, index); //jw
  };

  render() {
    const {
      onClick,
      //onClickIndex,
      props: {
        //activeTab,
        activeTabIndex,
        label,
        index, //jw
        //onClickIndex,//
      },
    } = this;

    let className = "tab-list-item";

    //if (activeTab === label) {
    if (activeTabIndex === index) className += " tab-list-active";
    return <li className={className}>
      <button type="button" aria-current={activeTabIndex === index ? "page" : undefined}
        onClick={onClick}>{label}</button>
    </li>;
  }
}

export default Tab;
