export const DECK_KEY = "lbh-web.deck.v1";
export const SETTINGS_KEY = "lbh-web.storage-settings.v1";
export const PASSPHRASE_KEY = "lbh-web.passphrase.v1";
export const REPEAT_OFFSETS_KEY = "lbh-web.repeat-offsets.v1";
export const DEFAULT_REPEAT_OFFSETS = [5, 10, 15];
export const HOUR = 60 * 60 * 1000;
export const DEFAULT_EXPIRY_HOURS = 24;

export function validExpiryHours(value) {
  return Number.isFinite(value) && value >= 1 && value <= 8760;
}

export function validRepeatOffset(value) {
  return Number.isSafeInteger(value) && value > 0;
}

export function readRepeatOffsets(storage) {
  try {
    const values = JSON.parse(storage.getItem(REPEAT_OFFSETS_KEY));
    if (Array.isArray(values) && values.length === 3 && values.every(validRepeatOffset)) {
      return values;
    }
  } catch {
    // Fall back to defaults if browser storage is unavailable or malformed.
  }
  return [...DEFAULT_REPEAT_OFFSETS];
}

export function readExpiryHours(storage) {
  try {
    const value = JSON.parse(storage.getItem(SETTINGS_KEY));
    return validExpiryHours(value) ? value : DEFAULT_EXPIRY_HOURS;
  } catch {
    return DEFAULT_EXPIRY_HOURS;
  }
}

export function readDeck(storage, now = Date.now()) {
  const raw = storage.getItem(DECK_KEY);
  if (!raw) return null;
  try {
    const deck = JSON.parse(raw);
    const validCards = (cards) => Array.isArray(cards) && cards.every((card) =>
      card && typeof card.question === "string" && typeof card.answer === "string"
    );
    if (deck.version !== 1 || !Number.isFinite(deck.expiresAt) ||
        deck.expiresAt <= now || !validCards(deck.QuizItems) ||
        !validCards(deck.MemorizedQuizItems) || typeof deck.fileContent !== "string" ||
        !["|", ","].includes(deck.fileSeparator)) {
      throw new Error("Invalid or expired deck");
    }
    return deck;
  } catch {
    storage.removeItem(DECK_KEY);
    return null;
  }
}

export function writeDeck(storage, state) {
  // Keep deck data separate from the remembered passphrase and transient UI state.
  storage.setItem(DECK_KEY, JSON.stringify({
    version: 1,
    QuizItems: state.QuizItems,
    MemorizedQuizItems: state.MemorizedQuizItems,
    fileContent: state.fileContent,
    fileSeparator: state.fileSeparator,
    hasLoadedDeck: state.hasLoadedDeck,
    expiresAt: state.expiresAt,
  }));
}
