import { LanguageContext, createTranslator } from "../helpers/i18n";
import React, { Component } from "react";
//import Translate from "react-translate-component";
// import counterpart from "counterpart";
import FramedSection from "./FramedSection.js";
import PropTypes from "prop-types";

class QuestionAnswer extends Component {
  static contextType = LanguageContext;

  constructor(props) {
    super(props);

    this.state = {
      // onButtonClickHandler: props.buttonClicked,
      quizQuestion: "",
      quizAnswer: "",
    };

  }

  resetToOriginal(){
     this.setState({ quizQuestion:this.props.currentQuizItem?.question ?? "", quizAnswer: this.props.currentQuizItem?.answer ?? "" });
  }

//   updateOriginal(){
//     if(!this.props.currentQuizItem) return;
//     this.props.currentQuizItem.question = this.state.quizQuestion;
//     this.props.currentQuizItem.answer = this.state.quizAnswer; 
//  }
updateOriginal() {
  this.props.onUpdateCurrentItem({
    question: this.state.quizQuestion,
    answer: this.state.quizAnswer,
  });
}

  componentDidMount() {
    this.resetToOriginal();
  }

  componentDidUpdate(prevProps) {
    //this is called after we deleted an item
    // console.log("QuestionAnswer::componentDidUpdate")
    if (this.props.currentQuizItem !== prevProps.currentQuizItem) {
      this.setState({ quizQuestion:this.props.currentQuizItem?.question, quizAnswer: this.props.currentQuizItem?.answer });
    }
  }

  
  render() {
    const t = createTranslator(this.context);
    // console.log(this.props.currentQuizItem?.question)
    const placeholderQ = "";// counterpart.translate("placeholderQ");
    const placeholderA = "";// counterpart.translate("placeholderA");
    const addCard = t("update"); //counterpart.translate("addCard");
    return (
      <table style={{width:"100%",height: "100%"}} >
        <tbody>
          <tr>
            <td >
            <FramedSection title={t("question")}>
              <textarea
                style={{width:"100%"}}
                name="q"
                aria-label={t("editQuestion")}
                disabled={!this.props.hasItem}
                cols="60"
                rows="10"
                placeholder={placeholderQ}
                //defaultValue={this.state.quizQuestion}
                value={this.state.quizQuestion}
                onChange={(e) =>
                  this.setState({ quizQuestion: e.target.value })
                }
              ></textarea>
              </FramedSection>
            </td>
          </tr>
          <tr>
            <td>
            <FramedSection title={t("answer")}>
              <textarea
                style={{width:"100%"}}
                name="a"
                aria-label={t("editAnswer")}
                disabled={!this.props.hasItem}
                cols="60"
                rows="15"
                placeholder={placeholderA}
                //defaultValue={this.state.quizAnswer}
                value={this.state.quizAnswer}
                onChange={(e) => this.setState({ quizAnswer: e.target.value })}
              ></textarea>
              </FramedSection>
            </td>
          </tr>
          <tr>
            <td>
              <button className="primary-button" disabled={!this.props.hasItem} onClick={() => this.updateOriginal()}>{addCard}</button>
              <button disabled={!this.props.hasItem} onClick={() => this.resetToOriginal()}>{t("reset")}</button>
              <button disabled={!this.props.hasItem} onClick={() => this.props.deleteCurrentEntirely()}>{t("deleteCard")}</button>
            </td>
          </tr>
        </tbody>
      </table>
    );
  }
}

QuestionAnswer.propTypes = {
  currentQuizItem: PropTypes.object.isRequired,//what to show
  hasItem: PropTypes.bool.isRequired,
   onUpdateCurrentItem: PropTypes.func.isRequired,
  deleteCurrentEntirely: PropTypes.func.isRequired,
  // isAnswerMonospaceFont: bool,
  // isAnswerLeftAligned : bool,
  // isQuestionMonospaceFont: bool,
  // isQuestionLeftAligned : bool,
  // aFontSize: PropTypes.number,
  // qFontSize: PropTypes.number,
};

export default QuestionAnswer;
