import { LanguageContext, createTranslator } from "../helpers/i18n";
import "./UserCardPlayer.css";
import PropTypes from "prop-types";
import React, { Component } from "react";
import NextTimeSelector from "./NextTimeSelector";

export default class UserCardPlayer extends Component {
  static contextType = LanguageContext;

  static propTypes = {
    QuizItems: PropTypes.array.isRequired,
    goToNextItem: PropTypes.func.isRequired,
    onShowInNCards: PropTypes.func.isRequired,
    repeatOffsets: PropTypes.arrayOf(PropTypes.number).isRequired,
    isActive: PropTypes.bool,
  };

  componentDidMount() {
    window.addEventListener("keydown", this.handleKeyDown);
  }

  componentWillUnmount() {
    window.removeEventListener("keydown", this.handleKeyDown);
  }

  handleKeyDown = (event) => {
    if (this.props.isActive === false || !this.props.QuizItems.length ||
        event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const target = event.target;
    if (target.closest && target.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])')) return;
    const index = ["1", "2", "3"].indexOf(event.key);
    if (index === -1 && event.key !== " ") return;
    event.preventDefault();
    if (event.repeat) return;
    if (index !== -1) this.props.onShowInNCards(this.props.repeatOffsets[index]);
    else this.props.goToNextItem();
  };

  render() {
    const t = createTranslator(this.context);
    const hasItems = this.props.QuizItems.length > 0;
    return (
      <div className="Toolbar" aria-label={t("reviewActions")}>
        <div className="review-action">
          <NextTimeSelector disabled={!hasItems}
            offsets={this.props.repeatOffsets}
            onNextTimeSelected={this.props.onShowInNCards} />
        </div>
        <div className="review-action">
          <button className="memorize-button" aria-label={t("markMemorized")} aria-keyshortcuts="Space" disabled={!hasItems} onClick={this.props.goToNextItem}>
            <span aria-hidden="true">✓</span> {t("markMemorized")}
            <kbd aria-hidden="true">SP</kbd>
          </button>
        </div>
      </div>
    );
  }
}
