import React from "react";
import en from "../lang/en";
import ru from "../lang/ru";

export const LANGUAGE_KEY = "lbh-web.interface-language.v1";
export const LANGUAGES = [
  { code: "en-US", label: "English" },
  { code: "ru-RU", label: "Русский" },
];

export function readLanguage(storage) {
  try {
    const language = storage.getItem(LANGUAGE_KEY);
    if (LANGUAGES.some(({ code }) => code === language)) return language;
  } catch {
    // The interface still works when browser storage is unavailable.
  }
  return "en-US";
}

export function createTranslator(language = "en-US") {
  const translations = language === "ru-RU" ? ru : en;
  return (key, values = {}) => {
    const message = translations[key] ?? en[key] ?? key;
    return message.replace(/\{(\w+)\}/g, (match, name) => values[name] ?? match);
  };
}

export function repeatLabel(language, count) {
  const category = new Intl.PluralRules(language).select(count);
  return createTranslator(language)(`repeat_${category}`, { count });
}

export const LanguageContext = React.createContext("en-US");
