import React from "react";
import PropTypes from "prop-types";
import { LANGUAGES, createTranslator } from "../helpers/i18n";

export default function LangCombo({ language, onChange }) {
  return <select aria-label={createTranslator(language)("interfaceLanguage")} value={language} onChange={onChange}>
    {LANGUAGES.map(({ code, label }) => <option key={code} value={code}>{label}</option>)}
  </select>;
}

LangCombo.propTypes = {
  language: PropTypes.string.isRequired,
  onChange: PropTypes.func.isRequired,
};
