
import React  from "react";
import PropTypes from "prop-types";
import "./FramedSection.css";

export default function FramedSection(props){
    return <>
<fieldset className="settingsSection">
<legend  className="fsLegend">{props.title}</legend>
{props.children}
</fieldset>
    </>
  }

  FramedSection.propTypes = {
    children:  PropTypes.oneOfType([PropTypes.array,PropTypes.object]), //instanceOf(), //array, //.isRequired,//what to show
    // onChange: PropTypes.func.isRequired,//what to show
    title: PropTypes.string.isRequired,//what to show
  };